// Airfield-lighting fixture loader (docs/research/environment_spec.md §5.1, step 0 / gate A-FIX).
// Converts data/sfo_lighting.js (generated by tools/env/build_lighting_spec.py from lighting_spec.json +
// lighting_fixtures.json) into one static record per emitting fixture FACE, in the app world frame (x east, y up,
// z south, metres from the ARP). Renderer-agnostic, no DOM: runs in Node (tools/env/test_fixtures.mjs) and in the
// browser. The per-frame intensity (controller step × beam × Allard visibility, §5.3–5.4, §4.10) is step 2 and is NOT
// computed here: records carry the photometric inputs (cd, beam limits, aim) and their provenance.
//
// Record (extends the renderers' sprite record {p, c, i, s, dir, k}):
//   p        [x, y, z] m; y = groundY + h (fixture height above local ground), ALS = the light plane at the landing
//            threshold elevation (JO 6850.2C 201a, spec §5.6: y = groundY + (thr elev − field elev) × 0.3048)
//   c        linear-sRGB colour: EB 67D chromaticity-box centroid, gamut-clipped (LIGHTING_SPEC.colours.*.lin_srgb, §4.11)
//   colour   W/Y/G/R/B code (lighting_fixtures.json colour_codes)
//   dir      unit emission direction [x, y, z] (y from aim_up_deg), null = omni; toe-in/out kept as toeIn/toeOut for
//            the step-2 beam function (their sign depends on the side of the CL)
//   k        directional lobe exponent for the sprite shaders: cos(θ_h,half) = 0.5^(1/k) at the half-width of the
//            main beam in azimuth (the 46F main-beam ellipse is the photometric truth; k is the cheap renderer proxy, I)
//   cd       minimum average main-beam intensity for the colour (AC 150/5345-46F Tables 3-1..3-3 via
//            LIGHTING_SPEC.fixtures), null when the photometry is NV (ALS lamps, flashers: §5.4 "photometry NV")
//   i        null: set per frame by the controller (step 2)
//   s        sprite size hint (m): 0.3 (I, the old js/anim/lights.js scale)
//   system, end, type, ftype (photometry key), face (face name in the group), seenBy
//   prov     group provenance string (pub / std / obs / inf combinations, lighting_spec.json provenance)
//   provClass  'pub' | 'std' | 'inf' | 'NV' — the QA overlay tint class (§11.4: pub/obs green, std blue, inf orange,
//            NV red): NV when the group is flagged runway_nv; else the weakest tag present (inf < std < pub/obs)
//   photometryNV  true when cd is unknown (cd null)
//   station (ALS ft from the landing threshold), seq (flasher firing order), aim (PAPI aiming angle deg, HG4 set)
export const COLOUR_NAME = { W: 'white', Y: 'yellow', G: 'green', R: 'red', B: 'blue' };
const FACE_COLOUR = { white: 'W', yellow: 'Y', green: 'G', red: 'R', blue: 'B' };
const FT = 0.3048;
// field elevation 13.1 ft (FAA NASR APT_BASE ELEV / AirNav; js/geo.js GROUND_Y = field level)
export const FIELD_ELEV_FT = 13.1;

// fixture "type" text in lighting_fixtures.json -> photometry key in LIGHTING_SPEC.fixtures (AC 150/5345-46F etc.)
export function photometryKey(type) {
  const t = String(type || '');
  if (/^PAPI_LHA/.test(t)) return 'PAPI_LHA';
  if (/^L-849/.test(t)) return 'L-849E_REIL';
  if (/^ALS_PAR56_300W/.test(t)) return 'ALS_PAR56_300W';
  if (/^SFL_flasher/.test(t)) return 'SFL_flasher';
  const m = t.match(/^(L-8\d\d[A-Z]?)/);
  return m ? m[1] : null;
}

function cdFor(spec, ftype, colourName) {
  const F = ftype && spec.fixtures[ftype];
  if (!F) return null;
  if (F.cd && typeof F.cd === 'object' && F.cd[colourName] != null && typeof F.cd[colourName] === 'number') return F.cd[colourName];
  if (typeof F.cd === 'number') return F.cd;
  if (Array.isArray(F.beams)) { const b = F.beams.find(b => b.colour === colourName); if (b && typeof b.cd === 'number') return b.cd; }
  return null;
}
function lobeK(spec, ftype) {
  const F = ftype && spec.fixtures[ftype]; const main = F && (F.main || (F.beams && F.beams[0] && F.beams[0].main));
  if (!main || !Array.isArray(main.h)) return 8;                    // I: default lobe when no beam is tabled
  const half = Math.max(1, (main.h[1] - main.h[0]) / 2) * Math.PI / 180;
  return Math.max(1, Math.log(0.5) / Math.log(Math.cos(half)));      // cos(half)^k = 0.5
}
export function provClassOf(prov, nv) {
  if (nv) return 'NV';
  const p = String(prov || '');
  if (/inf/.test(p)) return 'inf';
  if (/std/.test(p)) return 'std';
  return 'pub';
}

// light-plane height per ALS end: landing threshold elevation − field elevation (spec §5.6)
function alsPlane(spec) {
  const out = {};
  for (const R of spec.runways || []) for (const [E, e] of Object.entries(R.ends || {})) {
    const el = e.landing_threshold && e.landing_threshold.elev_ft;
    if (el != null) out[E] = (el - FIELD_ELEV_FT) * FT;
  }
  return out;
}

/** Load all fixture faces. opts.groundY (default 3, js/geo.js GROUND_Y). Returns {records, groups, counts}. */
export function loadFixtures(FIX, SPEC, opts = {}) {
  const groundY = opts.groundY ?? 3;
  const plane = alsPlane(SPEC);
  const colours = SPEC.colours;
  const records = [];
  const counts = { fixtures: {}, faces: {} };   // fixtures: system -> n points; faces: "system|end|seenBy" -> {W: n, ...}
  for (const g of FIX.groups) {
    counts.fixtures[g.system] = (counts.fixtures[g.system] || 0) + g.n;
    const ftype = photometryKey(g.type);
    const nv = !!g.runway_nv;
    const pc = provClassOf(g.prov, nv);
    const isALS = /^als_/.test(g.system);
    const faces = Object.entries(g.emit);
    const ftypeInpav = g.inpav_type ? photometryKey(g.inpav_type) : null;
    for (let pi = 0; pi < g.pts.length; pi++) {
      const pt = g.pts[pi];
      const [x, z, h] = pt;
      // in-pavement points of an edge / threshold / end group (builder flag inpav, review truth2-8): L-850C / L-850D
      // photometry, drawn at h = 1/2 in above the pavement (tools/env/build_lighting_spec.py IN_PAVEMENT_H)
      const inpav = !!(g.inpav && g.inpav[pi]);
      const ft = inpav && ftypeInpav ? ftypeInpav : ftype;
      const y = groundY + (isALS ? (plane[g.end] ?? 0) : 0) + (h || 0);
      faces.forEach(([face, em], fi) => {
        // colour of this face: 'face0'/'face1' -> per-point code (pts[3+fi]); 'split' (PAPI) -> W/R by angle (both
        // records); named faces (white/green/red/...) -> that colour
        let codes;
        if (face === 'face0' || face === 'face1') codes = [pt[3 + (face === 'face1' ? 1 : 0)]];
        else if (face === 'split') codes = ['W', 'R'];
        else codes = [FACE_COLOUR[face]];
        for (const code of codes) {
          if (!code || code === '-') { const key = g.system + '|' + g.end + '|' + em.seen_by; (counts.faces[key] ||= {})['-'] = (counts.faces[key]['-'] || 0) + 1; continue; }
          const cname = COLOUR_NAME[code];
          let d2 = null;
          if (Array.isArray(em.emit_dir)) d2 = em.emit_dir;
          else if (g.system === 'rwsl_rel') d2 = [pt[3], pt[4]];
          let dir = null;
          if (d2) {
            const up = (em.aim_up_deg || 0) * Math.PI / 180;
            dir = [d2[0] * Math.cos(up), Math.sin(up), d2[1] * Math.cos(up)];
          }
          const cd = cdFor(SPEC, ft, cname);
          const rec = {
            p: [x, y, z], c: (colours[cname] && colours[cname].lin_srgb) || [1, 1, 1], colour: code, dir, k: dir ? lobeK(SPEC, ft) : 0,
            cd, i: null, s: 0.3, system: g.system, end: g.end, type: inpav ? g.inpav_type : g.type, ftype: ft, inpav, face, seenBy: em.seen_by,
            prov: g.prov, provClass: pc, photometryNV: cd == null,
          };
          if (em.aim_up_deg) rec.aimUp = em.aim_up_deg;
          if (em.toe_in_deg) rec.toeIn = em.toe_in_deg;
          if (em.toe_out_deg) rec.toeOut = em.toe_out_deg;
          if (g.system === 'papi') rec.aim = pt[3];
          if (isALS && pt.length > 3) rec.station = pt[3];
          if (g.system === 'als_flasher' && pt.length > 4) rec.seq = pt[4];
          if (nv) rec.nv = g.runway_nv;
          records.push(rec);
          const key = g.system + '|' + g.end + '|' + em.seen_by;
          (counts.faces[key] ||= {})[code] = (counts.faces[key][code] || 0) + 1;
        }
      });
    }
  }
  return { records, groups: FIX.groups, counts };
}

/** QA overlay colours for ?qa=prov (§11.4): pub/obs green, std blue, inf orange, NV red (linear sRGB). */
export const PROV_TINT = { pub: [0.05, 1.0, 0.1], std: [0.1, 0.3, 1.0], inf: [1.0, 0.35, 0.0], NV: [1.0, 0.0, 0.0] };
export function provCounts(records) {
  const out = { pub: 0, std: 0, inf: 0, NV: 0, photometryNV: 0 };
  for (const r of records) { out[r.provClass]++; if (r.photometryNV) out.photometryNV++; }
  return out;
}
